schema_ddl:
CREATE TABLE dipartimenti (
    id SERIAL PRIMARY KEY,
    nome_dipartimento TEXT NOT NULL UNIQUE,
    budget_annuale NUMERIC(12,2) CHECK (budget_annuale >= 0)
);

CREATE TABLE dipendenti (
    id SERIAL PRIMARY KEY,
    nome_dipendente TEXT NOT NULL,
    cognome_dipendente TEXT NOT NULL,
    data_assunzione DATE NOT NULL,
    salario_mensile NUMERIC(10,2) CHECK (salario_mensile >= 0),
    dipartimento_id INT NOT NULL REFERENCES dipartimenti(id)
);
